import { useState, useCallback } from "react";
import styled from 'styled-components';
import { StudioProApi } from "@mendix/extensions-api";

import { AppSelectorNoVersionIcon } from "@mendix/ide-icons/AppSelectorNoVersionIcon";
import { EditIcon } from "@mendix/ide-icons/EditIcon";
import { MicroflowIcon } from "@mendix/ide-icons/MicroflowIcon";
import { PageIcon } from "@mendix/ide-icons/PageIcon";
import { ResizableTableContainer, type Selection } from '@mendix/ide-ui-components/table/Table';
import { ToolbarButton } from "@mendix/ide-ui-components/toolbar/ToolbarButton";

import { Agent } from "../../types/agent";
import { handleEditTool, handleDeleteTool } from "./agentHandlers";

import FormDivider from "../components/FormDivider";
import Table from "../components/Table";
import TextWithIcon from "../components/TextWithIcon";
import { Checkbox } from "@mendix/ide-ui-components/checkbox/Checkbox";

interface ToolsTableProps {
    agent: Agent;
    studioPro: StudioProApi;
    componentName: string;
    updateStudioProDocument: (agent: Agent) => Promise<void>;
    onAgentChange: (updatedAgent: Agent) => void;
}

const ToolsTable: React.FC<ToolsTableProps> = ({
    agent,
    studioPro,
    componentName,
    updateStudioProDocument,
    onAgentChange
}) => {
    const [selectedToolKeys, setSelectedToolKeys] = useState<Selection>([]);

    const addTool = useCallback(async () => {
        const updatedAgent = await handleEditTool(studioPro, componentName, agent, updateStudioProDocument);
        if (updatedAgent) {
            onAgentChange(updatedAgent);
        }
    }, [studioPro, agent]);

    const editTool = useCallback(async () => {
        const selectedIndex = Number(selectedToolKeys[0]);
        if (selectedToolKeys.length === 0 || !agent.tools || selectedIndex <= -1) {
            return;
        }

        const updatedAgent = await handleEditTool(studioPro, componentName, agent, updateStudioProDocument, selectedIndex);

        if (updatedAgent) {
            onAgentChange(updatedAgent);
        }
    }, [studioPro, agent, selectedToolKeys]);

    const deleteTool = useCallback(async () => {
        const selectedIndex = Number(selectedToolKeys[0]);
        if (selectedToolKeys.length === 0 || !agent.tools || selectedIndex <= -1) {
            return;
        }

        const updatedAgent = await handleDeleteTool(agent, updateStudioProDocument, selectedIndex);

        if (updatedAgent) {
            onAgentChange(updatedAgent);
        }
    }, [agent, selectedToolKeys]);

    const setEnabled = useCallback(async (toolName: string, isEnabled: boolean) => {
        if (!agent.tools) {
            return;
        }
        console.log(`Setting tool ${toolName} enabled state to ${isEnabled}`);
        const updatedTools = agent.tools.map(tool =>
            tool.name === toolName ? { ...tool, enabled: isEnabled } : tool
        );
        const updatedAgent = { ...agent, tools: updatedTools };
        updateStudioProDocument(updatedAgent);
        onAgentChange(updatedAgent);
    }, [agent]);

    const StyledCheckbox = styled(Checkbox)`
        pointer-events: auto;
        position: relative;
        z-index: 10;
    `;

    return (
        <FormDivider label="Tools">
            <ResizableTableContainer>
                <Table
                    ariaLabel="Tools table"
                    columns={[
                        { id: "enabled", caption: "Active", minWidth: 43, defaultWidth: 43, maxWidth: 43 },
                        { id: "name", caption: "Name", isRowHeader: true, resizable: true },
                        { id: "description", caption: "Description", resizable: true },
                        { id: "tool", caption: "Tool", useContentWrapper: true, resizable: true }
                    ]}
                    data={agent.tools ? agent.tools.map(tool => [
                        <StyledCheckbox
                            aria-label="Enabled"
                            isSelected={tool.enabled}
                            onChange={(isEnabled) => setEnabled(tool.name, isEnabled)}
                        />,
                        tool.name,
                        tool.description || "",
                        <TextWithIcon
                            icon={<MicroflowIcon />}
                            text={tool.microflow || ""}
                        />
                    ]) : []}
                    emptyMessage="No tools configured."
                    selectionType="row"
                    selectionMode="single"
                    selectedKeys={selectedToolKeys}
                    onDoubleClick={editTool}
                    onSelectionChange={setSelectedToolKeys}
                    toolbarLeft={
                        <>
                            <ToolbarButton
                                icon={<PageIcon />}
                                label="New"
                                aria-label={"Add new tool"}
                                tooltip="Add new tool"
                                onPress={addTool}
                            />
                            <ToolbarButton
                                icon={<EditIcon />}
                                label="Edit"
                                aria-label={"Edit selected tool"}
                                onPress={editTool}
                                tooltip="Edit selected tool"
                                isDisabled={selectedToolKeys.length === 0}
                            />
                            <ToolbarButton
                                icon={<AppSelectorNoVersionIcon />}
                                label="Delete"
                                aria-label={"Delete selected tool"}
                                onPress={deleteTool}
                                tooltip="Delete selected tool"
                                isDisabled={selectedToolKeys.length === 0}
                            />
                        </>
                    }
                />
            </ResizableTableContainer>
        </FormDivider>
    );
};

export default ToolsTable;
